library Parity version '1.0.0'
using FHIR version '4.0.1'
context Patient

// # %% [name: IsAdult]
define IsAdult: Patient.gender = 'male'

// # %% [name: Rollup]
define Rollup: exists({ IsAdult })

// # %%
define "Combined": IsAdult and Rollup

// # %% [name: IgnoreStrings]
define IgnoreStrings: 'IsAdult' = 'Rollup'

