library Adv version '1.0.0'
using FHIR version '4.0.1'
context Patient

// # %% [name: Base]
define Base: 1

// # %% [name: Outer]
define Outer: Base + 1

// # %%
define "Combined": Outer and Base

// # %% [name: IgnoreStrings]
define IgnoreStrings: 'Base' = 'Outer'

// # %% [name: Fn]
define function Fn(X Integer): X + 1

// # %%
define UsesFn: Fn(3)
